  # Renderiza um ícone SVG decorativo que herda a cor do texto (currentColor).
  #   = icon :lock
  #   = icon :eye, class: "icone--grande", data: { ... }
  def icon(nome, **opcoes)
    tracos = ICONES.fetch(nome.to_sym)
    classes = [ "icone", opcoes.delete(:class) ].compact.join(" ")

    tag.svg(tracos.html_safe, xmlns: "http://www.w3.org/2000/svg", viewBox: "0 0 24 24",
            fill: "none", stroke: "currentColor", "stroke-width": 2,
            "stroke-linecap": "round", "stroke-linejoin": "round",
            "aria-hidden": true, focusable: false, class: classes, **opcoes)
  end
